import numpy as np
from scipy.optimize import minimize
import math

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

def _fast_sa_seed(seed):
    np.random.seed(seed)
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 5)
    xv, yv = np.meshgrid(xs, ys)
    centers = np.vstack([xv.ravel(), yv.ravel()]).T[:N]
    radii = np.full(N, 0.08)

    def _quick_correct(c, r):
        for i in range(N): r[i] = min(r[i], c[i,0], 1-c[i,0], c[i,1], 1-c[i,1])
        for i in range(N):
            for j in range(i + 1, N):
                dist = np.linalg.norm(c[i] - c[j])
                rad_sum = r[i] + r[j]
                if dist < rad_sum and rad_sum > 0:
                    scale = dist / rad_sum
                    r[i] *= scale; r[j] *= scale
        return c, np.maximum(r, 1e-9)

    centers, radii = _quick_correct(centers, radii)
    temp = 0.5; alpha = 0.98
    for _ in range(150):
        idx = np.random.randint(N)
        pert = (np.random.rand(2) - 0.5) * 0.2 * temp
        centers[idx] = np.clip(centers[idx] + pert, 0, 1)
        radii[idx] *= (1 + (np.random.rand() - 0.5) * 0.3 * temp)
        centers, radii = _quick_correct(centers, radii)
        temp *= alpha

    z = np.zeros(N * 3)
    z[0::3] = centers[:, 0]; z[1::3] = centers[:, 1]; z[2::3] = radii
    return z

# --- SLSQP formulation with Analytic Jacobians (inspired by Noesis I) ---
def objective(z): return -np.sum(z[2::3])
def objective_jac(z):
    g = np.zeros_like(z); g[2::3] = -1.0; return g

def ineq_boundary(z):
    x, y, r = z[0::3], z[1::3], z[2::3]
    return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
def jac_boundary(z):
    J = np.zeros((4*N, 3*N));
    for i in range(N):
        xi, yi, ri = 3*i, 3*i+1, 3*i+2
        J[i, xi] = 1.0; J[i, ri] = -1.0
        J[N+i, xi] = -1.0; J[N+i, ri] = -1.0
        J[2*N+i, yi] = 1.0; J[2*N+i, ri] = -1.0
        J[3*N+i, yi] = -1.0; J[3*N+i, ri] = -1.0
    return J

def ineq_nonoverlap(z):
    centers = np.vstack((z[0::3], z[1::3])).T; r = z[2::3]
    diff = centers[:, None, :] - centers[None, :, :]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    iu = np.triu_indices(N, 1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])
def jac_nonoverlap(z):
    centers = np.vstack((z[0::3], z[1::3])).T
    m = N*(N-1)//2; J = np.zeros((m, 3*N))
    idx = 0
    for i in range(N):
        for j in range(i+1, N):
            xi, yi, ri = 3*i, 3*i+1, 3*i+2
            xj, yj, rj = 3*j, 3*j+1, 3*j+2
            dx = centers[i,0] - centers[j,0]
            dy = centers[i,1] - centers[j,1]
            d = math.hypot(dx, dy)
            invd = 1.0 / d if d > 1e-12 else 0.0
            J[idx, xi] = dx * invd; J[idx, yi] = dy * invd; J[idx, ri] = -1.0
            J[idx, xj] = -dx * invd; J[idx, yj] = -dy * invd; J[idx, rj] = -1.0
            idx += 1
    return J

def _run_slsqp_optimization(initial_guess):
    bounds = []
    for i in range(N): bounds.extend([(0,1), (0,1), (R_MIN, 0.5)])
    constraints = [
        {'type': 'ineq', 'fun': ineq_boundary,   'jac': jac_boundary},
        {'type': 'ineq', 'fun': ineq_nonoverlap, 'jac': jac_nonoverlap},
    ]
    res = minimize(objective, initial_guess, method='SLSQP', jac=objective_jac,
                   bounds=bounds, constraints=constraints,
                   options={'maxiter': 200, 'ftol': 1e-9})
    p = res.x
    centers = np.vstack((p[0::3], p[1::3])).T; radii = p[2::3]
    return centers, radii

def _ensure_validity(centers, radii):
    n = centers.shape[0];
    for i in range(n): radii[i] = min(radii[i], centers[i,0], 1-centers[i,0], centers[i,1], 1-centers[i,1])
    for _ in range(10):
        violations = 0
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.linalg.norm(centers[i] - centers[j])
                rad_sum = radii[i] + radii[j]
                if dist < rad_sum:
                    violations += 1
                    if rad_sum > 0: scale = (dist / rad_sum) * (1.0-SAFETY); radii[i] *= scale; radii[j] *= scale
        if violations == 0: break
    return centers, np.maximum(radii, 0)

def construct_packing() -> tuple:
    num_starts = 16
    best_score = -1
    best_packing = (None, None)
    for i in range(num_starts):
        initial_guess = _fast_sa_seed(seed=i)
        centers, radii = _run_slsqp_optimization(initial_guess)
        centers, radii = _ensure_validity(centers, radii)
        current_score = np.sum(radii)
        if current_score > best_score:
            best_score = current_score
            best_packing = (centers, radii)
    return best_packing
